@group(0) @binding(0) var<storage, read> b0: array<f32>;
@group(0) @binding(1) var<storage, read> b1: array<f32>;
@group(0) @binding(2) var<storage, read_write> bout: array<f32>;

@compute @workgroup_size(1024)
fn main(@builtin(local_invocation_index) lid: u32, @builtin(workgroup_id) wid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
    let tid: i32 = i32(lid);
    let bid: i32 = i32(wid.x) + i32(wid.y) * i32(nwg.x);
    if (bid >= 1i) { return; }
    var v_acc1: f32 = 0.0;
    var v_acc0: f32 = 0.0;
    var v_in0: f32 = 0.0;
    var v_in1: f32 = 0.0;
    var v_v0: f32 = 0.0;
    var n_e: i32 = 0i;
    n_e = ((1024i * bid) + tid);
    if (n_e < 4i) {
        v_acc1 = 0.0;
        for (var n_r0: i32 = 0i; n_r0 < 3i; n_r0 = n_r0 + 1i) {
            v_acc0 = 0.0;
            for (var n_r1: i32 = 0i; n_r1 < 2i; n_r1 = n_r1 + 1i) {
                v_in0 = b1[((((4i * (n_e % 2i)) + (24i * (n_e / 2i))) + (6i * n_r0)) + n_r1)];
                v_acc0 = (v_acc0 + v_in0);
            }
            v_acc1 = (v_acc1 + v_acc0);
        }
        v_in1 = b0[(n_e % 2i)];
        v_v0 = (v_acc1 / v_in1);
        bout[((n_e % 2i) + (2i * (n_e / 2i)))] = v_v0;
    }
}

